from pathlib import Path
import os, stat, hashlib, json
out={}
for name in ('CLAUDE.md','AGENTS.md'):
    p=Path('/work')/name
    try:
        st=p.lstat()
        kind='regular' if stat.S_ISREG(st.st_mode) else 'symlink' if stat.S_ISLNK(st.st_mode) else 'other'
        item={'exists_entry':True,'kind':kind,'size':st.st_size,'uid':st.st_uid,'mode':oct(stat.S_IMODE(st.st_mode))}
        if kind=='regular': item['sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
        if kind=='symlink': item['target']=os.readlink(p)
    except FileNotFoundError:
        item={'exists_entry':False}
    out[name]=item
